نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
ترکیب ریسک‌های ایمنی و زیست‌محیطی ماه را برای مدیرعامل خلاصه کن. مهم‌ترین اولویت کجاست؟ (مدیر HSE — مجتمع معدنی گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    },
    {
      "dataset": "permits",
      "description": "مجوزها و انطباق با شرایط",
      "dimensions": [
        "permit_type",
        "authority"
      ],
      "measures": [
        "status",
        "expiry_date",
        "violations"
      ]
    },
    {
      "dataset": "rehabilitation",
      "description": "وضعیت احیای اراضی تخریب‌شده",
      "dimensions": [
        "area",
        "period"
      ],
      "measures": [
        "disturbed_ha",
        "rehabilitated_ha",
        "target_ha"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "trifr",
      "description": "نرخ بروز حوادث قابل ثبت",
      "formula": "(تعداد حوادث قابل ثبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "rehabilitation_rate",
      "description": "نرخ احیای اراضی",
      "formula": "مساحت احیاشده / مساحت تخریب‌شده",
      "unit": "درصد",
      "dimensions": [
        "area"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

