      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
    },
    {
      "dataset": "supplier_performance",
      "description": "عملکرد تأمین‌کنندگان: تأخیر، کیفیت، قیمت",
      "dimensions": [
        "supplier",
        "period"
      ],
      "measures": [
        "on_time_pct",
        "quality_score",
        "lead_time_days"
      ]
    },
    {
      "dataset": "inventory_critical",
      "description": "موجودی قطعات حیاتی و نقطهٔ سفارش",
      "dimensions": [
        "item"
      ],
      "measures": [
        "current_stock",
        "reorder_point",
        "lead_time_days"
      ]
    }
